def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) >= 2:
                objects.append((color, min(y for y,x in cells), max(y for y,x in cells),
                                min(x for y,x in cells), max(x for y,x in cells)))

    out = [[bg] * w for _ in range(h)]
    for color, r1, r2, c1, c2 in objects:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if grid[r][c] != bg:
                    out[r][c] = color
    return out
